'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { RangeTree } = require('./src/range-tree');

const sum = (values, l, r) => values.slice(l, r).reduce((total, value) => total + value, 0);
const max = (values, l, r) => values.slice(l, r).reduce((largest, value) => Math.max(largest, value), -Infinity);
const first = (values, lo, x) => values.findIndex((value, i) => i >= lo && value >= x);

function check(tree, values) {
  assert.equal(tree.length, values.length);
  // Search before any operation that could incidentally push the pending tags.
  for (let lo = 0; lo <= values.length; lo++) {
    for (const x of [-Infinity, -30, -1, 0, 1, 30, Infinity]) {
      assert.equal(tree.firstAtLeast(lo, x), first(values, lo, x));
    }
  }
  for (let l = 0; l <= values.length; l++) {
    for (let r = l; r <= values.length; r++) {
      assert.equal(tree.sum(l, r), sum(values, l, r));
      assert.equal(tree.max(l, r), max(values, l, r));
    }
  }
  for (let i = 0; i < values.length; i++) assert.equal(tree.get(i), values[i]);
  const result = tree.toArray();
  assert.deepEqual(result, values);
  result[0] = 999;
  assert.equal(tree.get(0), values[0]);
}

test('assignments discard earlier additions at parent and child nodes', () => {
  const tree = new RangeTree([1, 2, 3, 4, 5, 6, 7, 8]);
  tree.add(0, 4, 7);
  tree.add(0, 8, 3);
  tree.assign(0, 8, -10);
  tree.add(0, 8, 2);
  assert.equal(tree.sum(2, 6), -32);
  check(tree, Array(8).fill(-8));
});

test('partial maximum queries preserve negative values', () => {
  const tree = new RangeTree([-9, -7, -5, -3, -1]);
  assert.equal(tree.max(1, 4), -3);
  tree.assign(0, 5, -20);
  tree.add(1, 4, 2);
  check(tree, [-20, -18, -18, -18, -20]);
});

test('threshold searches propagate pending assignments and additions', () => {
  const tree = new RangeTree([0, 0, 0, 0, 0]);
  tree.assign(0, 5, 10);
  assert.equal(tree.firstAtLeast(0, 10), 0);
  assert.equal(tree.firstAtLeast(3, 10), 3);
  tree.add(0, 5, -20);
  assert.equal(tree.firstAtLeast(0, 0), -1);
  tree.add(0, 5, 30);
  assert.equal(tree.firstAtLeast(2, 20), 2);
  tree.assign(0, 3, -1);
  assert.equal(tree.firstAtLeast(0, 20), 3);
  check(tree, [-1, -1, -1, 20, 20]);
});

test('mixed updates and queries agree with a deterministic array oracle', () => {
  let state = 0x12345678;
  const random = limit => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state % limit;
  };
  for (const n of [1, 2, 3, 5, 8, 17, 32]) {
    const values = Array.from({ length: n }, () => random(41) - 20);
    const tree = new RangeTree(values);
    for (let step = 0; step < 1200; step++) {
      let l = random(n + 1);
      let r = random(n + 1);
      if (l > r) [l, r] = [r, l];
      const value = random(41) - 20;
      switch (random(6)) {
        case 0:
          assert.equal(tree.assign(l, r, value), undefined);
          for (let i = l; i < r; i++) values[i] = value;
          break;
        case 1:
          assert.equal(tree.add(l, r, value), undefined);
          for (let i = l; i < r; i++) values[i] += value;
          break;
        case 2:
          assert.equal(tree.sum(l, r), sum(values, l, r));
          break;
        case 3:
          assert.equal(tree.max(l, r), max(values, l, r));
          break;
        case 4:
          assert.equal(tree.firstAtLeast(l, value), first(values, l, value));
          break;
        case 5: {
          const i = random(n);
          assert.equal(tree.get(i), values[i]);
          break;
        }
      }
      if (step % 100 === 99) check(tree, values);
    }
    check(tree, values);
  }
});

test('validation, empty ranges, copying, and read-only length retain their contract', () => {
  for (const input of [undefined, null, {}, [], [NaN], [Infinity], [-Infinity], ['1'], Array(2)]) {
    assert.throws(() => new RangeTree(input), RangeError);
  }
  const input = [3, -2, 7];
  const tree = new RangeTree(input);
  input[0] = 99;
  tree.add(0, 3, 4);
  const expected = [7, 2, 11];
  const invalidRanges = [[-1, 0], [0, 4], [2, 1], [0.5, 2], [0, 1.5], [NaN, 2], [0, Infinity], ['0', 2]];
  for (const [l, r] of invalidRanges) {
    for (const method of ['assign', 'add', 'sum', 'max']) {
      assert.throws(() => tree[method](l, r, 5), RangeError);
    }
  }
  for (const method of ['assign', 'add']) {
    for (const value of [NaN, Infinity, -Infinity, '1', undefined, null]) {
      assert.throws(() => tree[method](0, 3, value), RangeError);
      assert.throws(() => tree[method](2, 2, value), RangeError);
    }
    for (let i = 0; i <= 3; i++) assert.equal(tree[method](i, i, 10), undefined);
  }
  for (const i of [-1, 3, 0.5, NaN, Infinity, '0']) assert.throws(() => tree.get(i), RangeError);
  for (const lo of [-1, 4, 0.5, NaN, Infinity, '0']) assert.throws(() => tree.firstAtLeast(lo, 0), RangeError);
  for (const x of [NaN, undefined, null, '1']) assert.throws(() => tree.firstAtLeast(0, x), RangeError);
  assert.throws(() => { tree.length = 20; }, TypeError);
  check(tree, expected);
});
